local function values(): (number, number) return 1, 2 end
local list: {number} = {values()}
print(list)

local function values(): (number, string) return 1, "bad" end
local list: {number} = {values()}
print(list)

local function values(): (number, string) return 1, "unused" end
local list: {number} = {(values())}
print(list)

local object = {run = function(self) print(self) end}
object:
run()

local values: {number} = {1}
local key: string = "1"
print(values[key])

local values: {number} = {1}
values[1] = "bad"
print(values)

local M = {}
function M:message(value: string): string return value end
print(M:message("hi"), M.message(M, "ok"))

local M = {}
function M:message(value: string): string return value end
print(M:message(1))

local M = {}
M.nested = {}
M.nested.message = "hi"
local value: number = M.nested.message
print(value)

local M = {}
if math.random() > 0.5 then M.value = 1 else M.value = "hi" end
print(M.value)

local M = {value = 1}
M.value = nil
print(M.value)
